<?php
declare(strict_types=1);namespace Pam\Native\DevTools;use InvalidArgumentException;use JsonException;use Throwable;final class DevTools{private array$timeline=[];private array$marks=[];private int$nextId=1;private int$dropped=0;public function __construct(private readonly int$capacity=1024,private readonly Redactor$redactor=new Redactor()){if($capacity<32||$capacity>10000)throw new InvalidArgumentException('DevTools capacity must be between 32 and 10000.');}public function event(string$name,mixed$data=null):int{return$this->record(RecordKind::Event,$name,$data);}public function snapshot(string$name,mixed$state):int{return$this->record(RecordKind::StateSnapshot,$name,$state);}public function error(Throwable$error,array$context=[]):int{return$this->record(RecordKind::Error,$error::class,['message'=>$error->getMessage(),'file'=>$error->getFile(),'line'=>$error->getLine(),'trace'=>mb_substr($error->getTraceAsString(),0,16000),'context'=>$context]);}public function mark(string$name):void{$this->name($name);$this->marks[$name]=hrtime(true);}public function measure(string$name,string$from,?string$to=null):float{$this->name($name);if(!isset($this->marks[$from]))throw new InvalidArgumentException('Unknown performance mark: '.$from);$end=$to===null?hrtime(true):($this->marks[$to]??throw new InvalidArgumentException('Unknown performance mark: '.$to));$duration=max(0,($end-$this->marks[$from])/1_000_000);$this->record(RecordKind::Performance,$name,['from'=>$from,'to'=>$to,'durationMs'=>$duration]);return$duration;}public function network(string$method,string$url,array$headers=[],mixed$body=null):NetworkTransaction{$method=strtoupper($method);if(!preg_match('/^[A-Z]{3,12}$/D',$method)||filter_var($url,FILTER_VALIDATE_URL)===false)throw new InvalidArgumentException('Invalid network transaction.');return new NetworkTransaction($this,$this->nextId++,$method,$url,hrtime(true),['headers'=>$headers,'body'=>$body]);}public function finishNetwork(NetworkTransaction$t,int$start,int$end,NetworkState$state,array$request,array$response):void{$this->append(['id'=>$t->id,'kind'=>RecordKind::Network->value,'name'=>$t->method,'timestampNs'=>$start,'durationMs'=>max(0,($end-$start)/1_000_000),'data'=>$this->redactor->redact(['url'=>$t->url,'state'=>$state->value,'request'=>$request,'response'=>$response])]);}public function timeline():array{return$this->timeline;}public function clear():void{$this->timeline=[];$this->marks=[];$this->dropped=0;}public function metrics():array{$kinds=[];foreach(RecordKind::cases()as$kind)$kinds[$kind->value]=0;foreach($this->timeline as$row)$kinds[$row['kind']]++;return['records'=>count($this->timeline),'dropped'=>$this->dropped,'events'=>$kinds[1],'snapshots'=>$kinds[2],'network'=>$kinds[3],'performance'=>$kinds[4],'errors'=>$kinds[5]];}public function exportJson():string{return json_encode(['schemaVersion'=>1,'exportedAt'=>gmdate('c'),'metrics'=>$this->metrics(),'timeline'=>$this->timeline],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}private function record(RecordKind$kind,string$name,mixed$data):int{$this->name($name);$id=$this->nextId++;$this->append(['id'=>$id,'kind'=>$kind->value,'name'=>$name,'timestampNs'=>hrtime(true),'durationMs'=>0.0,'data'=>$this->redactor->redact($data)]);return$id;}private function append(array$row):void{while(count($this->timeline)>=$this->capacity){array_shift($this->timeline);$this->dropped++;}$this->timeline[]=$row;}private function name(string$name):void{if(!preg_match('/^[^\x00-\x1f]{1,160}$/u',$name))throw new InvalidArgumentException('Invalid DevTools record name.');}}
